INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (15, 'M15.23', 'Exam Question Bank', 23)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'A full-authority digital engine control (FADEC) receives the data necessary to:', '[{"id": "a", "text": "Control engine operation according to ambient temperature, pressure and humidity", "correct": false}, {"id": "b", "text": "Adjust a standard hydromechanical fuel control unit to obtain the most effective engine operation", "correct": false}, {"id": "c", "text": "Develop the commands to various actuators to control engine operation", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a typical dual loop fire detection system:', '[{"id": "a", "text": "Loop B is used for fire detection and loop A is used for overheat detection", "correct": false}, {"id": "b", "text": "Both loops are used for overheat and fire detection", "correct": true}, {"id": "c", "text": "Loop A is used for fire detection and loop B is used for overheat detection", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Generally when maximum APU shaft output power is being used in conjunction with pneumatic power:', '[{"id": "a", "text": "Pneumatic loading will be automatically modulated to maintain a safe EGT", "correct": true}, {"id": "b", "text": "Temperature limits and loads must be carefully monitored by the operator to maintain a safe EGT", "correct": false}, {"id": "c", "text": "Electrical loading will be automatically modulated to maintain a safe EGT", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'For approximately stoichiometric kerosene–air combustion, the fuel-to-air ratio is:', '[{"id": "a", "text": "15:1 by weight", "correct": false}, {"id": "b", "text": "1:15 by volume", "correct": false}, {"id": "c", "text": "1:15 by weight", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What may be installed in an engine mounting system to reduce critical engine-vibration frequencies?', '[{"id": "a", "text": "Vibration absorbers of calibrated weight", "correct": true}, {"id": "b", "text": "Spring cushioned mounting pads", "correct": false}, {"id": "c", "text": "Rubber encased wire mesh vibration isolators", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the purpose of an oil-damped main bearing in some gas turbine engines?', '[{"id": "a", "text": "Provide lubrication of bearing from the beginning of starting rotation until normal oil pressure is established", "correct": false}, {"id": "b", "text": "Dampen surges in oil pressure to the bearing", "correct": false}, {"id": "c", "text": "Provide an oil film between the outer race and the bearing housing in order to reduce vibration", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which duct area variation is characteristic of a supersonic air inlet?', '[{"id": "a", "text": "Progressively decreases and then increases in area from front to rear", "correct": true}, {"id": "b", "text": "Progressively increases in area from front to rear", "correct": false}, {"id": "c", "text": "Progressively increases and then decreases in area from front to rear", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Typically on a turbo fan when engine anti-icing is selected "ON" hot air is sent:', '[{"id": "a", "text": "To the intake cowl and sometimes to the intake guide vanes and bullet", "correct": true}, {"id": "b", "text": "To the intake cowl and splitter", "correct": false}, {"id": "c", "text": "To the intake guide vanes only", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'How are HP nozzle guide vanes usually cooled?', '[{"id": "a", "text": "By HP compressor discharge air", "correct": true}, {"id": "b", "text": "By fan discharge air", "correct": false}, {"id": "c", "text": "By LP turbine discharge air", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which statement describes a full-flow lubricating-oil system?', '[{"id": "a", "text": "There is no high-pressure filter", "correct": false}, {"id": "b", "text": "There are no scavenger pumps in the rear main bearing", "correct": false}, {"id": "c", "text": "The oil pressure varies according to the revolutions of the engine", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'When cracks are found on blades of the first turbine stage this is an indication of:', '[{"id": "a", "text": "Turbine over speed", "correct": false}, {"id": "b", "text": "Excessive turbine blade tip vibration", "correct": false}, {"id": "c", "text": "Turbine over temperature", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'A typical turbofan type turbine engine is lifted by mounts(hard points) located:', '[{"id": "a", "text": "On the fan and the high-pressure compressor flanges", "correct": false}, {"id": "b", "text": "On the fan and turbine frames", "correct": true}, {"id": "c", "text": "On the fan and turbine frames and the combustor flanges", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What may result from a defective labyrinth seal?', '[{"id": "a", "text": "An increase in oil consumption-an increase in the pressure breather system", "correct": true}, {"id": "b", "text": "An increase in oil consumption-no change in the pressure breather system", "correct": false}, {"id": "c", "text": "No change in oil consumption-a decrease in the pressure breather system", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Fuel additives to prevent freezing are usually added to the fuel:', '[{"id": "a", "text": "By the fuel manufacturer", "correct": true}, {"id": "b", "text": "By the operator on every refuel", "correct": false}, {"id": "c", "text": "By the operator when cold weather conditions are forecast", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An engine starter is not used during:', '[{"id": "a", "text": "Ground starting up", "correct": false}, {"id": "b", "text": "Ventilation", "correct": false}, {"id": "c", "text": "In flight starting up according to the speed of the aircraft and the altitude", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which airflow contributes principally to flame stabilisation in a combustion chamber?', '[{"id": "a", "text": "By primary air", "correct": true}, {"id": "b", "text": "By secondary air", "correct": false}, {"id": "c", "text": "By tertiary air", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'For a given gas flow through turbine nozzle guide vanes:', '[{"id": "a", "text": "Gas speed increases and static pressure decreases", "correct": true}, {"id": "b", "text": "Static pressure increases and gas speed increases", "correct": false}, {"id": "c", "text": "Gas speed remains constant and temperature decreases", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What normally happens to static pressure, total temperature and absolute airflow velocity through an axial-compressor rotor?', '[{"id": "a", "text": "Static pressure and total temperature increase, while absolute velocity decreases", "correct": false}, {"id": "b", "text": "Static pressure and total temperature increase, while absolute velocity is unchanged", "correct": false}, {"id": "c", "text": "Static pressure, total temperature and absolute velocity increase", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In principle the combustion process in a gas turbine engine takes place under:', '[{"id": "a", "text": "Increasing pressure-increasing volume", "correct": false}, {"id": "b", "text": "Increasing pressure-decreasing volume", "correct": false}, {"id": "c", "text": "Constant pressure-increasing volume", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a turboprop engine what type of gearing arrangement is used in the main reduction gear box?', '[{"id": "a", "text": "Helical gear type", "correct": false}, {"id": "b", "text": "Axial spar gear type", "correct": false}, {"id": "c", "text": "Epicyclic gear type", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a dual-spool turbine engine the starter rotates the:', '[{"id": "a", "text": "Low-pressure compressor", "correct": false}, {"id": "b", "text": "Aft turbine wheels", "correct": false}, {"id": "c", "text": "High-pressure compressor", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The EGT in a turbo jet engine is measured by using:', '[{"id": "a", "text": "Chromel/alumel thermocouples", "correct": true}, {"id": "b", "text": "Electrical resistance thermocouples", "correct": false}, {"id": "c", "text": "Iron/constant thermocouples", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'A torque indicating system is normally found on a:', '[{"id": "a", "text": "Turbojet engine", "correct": false}, {"id": "b", "text": "Turbofan engine", "correct": false}, {"id": "c", "text": "Turboprop engine", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Turbine blades removed for hot section inspection (HSI.) must be reinstalled:', '[{"id": "a", "text": "At 180 degrees position", "correct": false}, {"id": "b", "text": "In the same position", "correct": true}, {"id": "c", "text": "At 90 degrees position", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'How is an air intake for subsonic flight generally shaped?', '[{"id": "a", "text": "So that the air velocity will decrease and the static pressure will increase during passage of the air in the", "correct": true}, {"id": "b", "text": "So that the air velocity and the static pressure will increase during passage of the air in the intake", "correct": false}, {"id": "c", "text": "The flow area decreases in the flow direction", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The function of the exhaust nozzle is to:', '[{"id": "a", "text": "Reduce the noise and turbulence of the airflow", "correct": false}, {"id": "b", "text": "Convert the pressure of the airflow into speed", "correct": true}, {"id": "c", "text": "Add an aerodynamic shape to the end of the engine", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Why is expansion space provided in an engine oil tank?', '[{"id": "a", "text": "For oil enlargement and collection of foam", "correct": true}, {"id": "b", "text": "For proper oil tank ventilation", "correct": false}, {"id": "c", "text": "To eliminate oil foaming", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What does an APU starter duty cycle specify?', '[{"id": "a", "text": "How often the starter can be used consecutively with a short cool down time only", "correct": true}, {"id": "b", "text": "How long the starter is allowed to run continuously", "correct": false}, {"id": "c", "text": "After how many flight hours the starter must be replaced", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Precautions for short-term storage of installed engines should include:', '[{"id": "a", "text": "Regular engine run, installation of appropriate blanks and covers", "correct": true}, {"id": "b", "text": "Storage in dustproof cantainer", "correct": false}, {"id": "c", "text": "Installation of blanks and covers", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Anti-surge bleed valves:', '[{"id": "a", "text": "Increase compressor stability when open", "correct": true}, {"id": "b", "text": "Increase compressor stability when closed", "correct": false}, {"id": "c", "text": "Have no effect on compressor stability", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What technique is used on some modern high power gas turbine engines to minimize leakage across turbine blade tips?', '[{"id": "a", "text": "High-pressure gas sealing", "correct": false}, {"id": "b", "text": "Blade tip clearance control by close tolerance assembly", "correct": false}, {"id": "c", "text": "Active clearance control", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the principal mechanical function of the turbine section?', '[{"id": "a", "text": "Convert kinetic energy into potential energy", "correct": false}, {"id": "b", "text": "Power the compressor and engine accessories", "correct": true}, {"id": "c", "text": "Convert thermal energy into kinetic energy", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An advantage of the axial flow compressor is its:', '[{"id": "a", "text": "Low starting power requirements", "correct": false}, {"id": "b", "text": "High peak efficiency", "correct": true}, {"id": "c", "text": "Low weight", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'A ratiometer temperature indicator can be check calibrated in situ by:', '[{"id": "a", "text": "Disconnecting the bulb and substituting it with a decade resistance box", "correct": true}, {"id": "b", "text": "Connecting a decade resistance box in series with the power supply", "correct": false}, {"id": "c", "text": "Connecting a decade resistance box in series with the temperature bulb", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An EPR indicator reads slightly above 1.0 with the engine stopped. Which statement is most appropriate?', '[{"id": "a", "text": "No action is needed as this is not a fault condition", "correct": true}, {"id": "b", "text": "It means that the transmitter datum has shifted and the transmitter must be changed", "correct": false}, {"id": "c", "text": "The indicator is out of tolerance and must be readjusted to read 1", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Under normal FADEC operation, what is the effect of a channel-reset signal?', '[{"id": "a", "text": "Randomly select the active channel", "correct": false}, {"id": "b", "text": "Select the standby channel as the active channel", "correct": true}, {"id": "c", "text": "Always select channel A in reference to channel B", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'How is a helicopter turboshaft engine’s output speed adapted to the rotor drive?', '[{"id": "a", "text": "Inputted to a constant speed unit to keep rotor speed constant", "correct": false}, {"id": "b", "text": "Increased in a gear box before transmission to the helicopter rotors", "correct": false}, {"id": "c", "text": "Reduced in a gear box before transmission to the helicopter rotors", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the design objective for axial airflow velocity through an axial-flow compressor?', '[{"id": "a", "text": "Increase the axial speed of the air from inlet to outlet of the compressor", "correct": false}, {"id": "b", "text": "Maintain the axial speed of the air constant calculated at cruise rating", "correct": true}, {"id": "c", "text": "Maintain the axial speed of the air constant calculated at the ground engine idling", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In an axial flow turbine engine compressor bleed air is sometimes used to aid in cooling the:', '[{"id": "a", "text": "Turbine, vanes, blades and bearings", "correct": true}, {"id": "b", "text": "Compressor inlet guide vanes", "correct": false}, {"id": "c", "text": "Fuel", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Manufacturers normally require turbine engine oil servicing within a short time after engine shut down primarily to:', '[{"id": "a", "text": "Help dilute and neutralize any contaminants that may already be present in the engine''s oil system", "correct": false}, {"id": "b", "text": "Prevent over servicing", "correct": true}, {"id": "c", "text": "Provide a better indication of any oil leaks in the system", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The purpose of the bleed valve located in the intermediate stages of the compressor in an aircraft gas turbine engine is to:', '[{"id": "a", "text": "Vent some of the air overboard to prevent a compressor stall", "correct": true}, {"id": "b", "text": "Control excessively high RPM to prevent a compressor stall", "correct": false}, {"id": "c", "text": "Vent high ram air pressure overboard to prevent a compressor stall", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which faults commonly initiate an automatic APU shutdown?', '[{"id": "a", "text": "APU overspeed, fire detection and low quantity", "correct": false}, {"id": "b", "text": "Low oil pressure, low oil quantity and high oil temperature", "correct": false}, {"id": "c", "text": "APU fire detection, low oil pressure and high oil temperature", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The main limiting factor of turbine engine operation is the:', '[{"id": "a", "text": "Compressor inlet air temperature", "correct": false}, {"id": "b", "text": "Turbine inlet air temperature", "correct": true}, {"id": "c", "text": "Combustion chamber pressure", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The ignition system is not used in the case of:', '[{"id": "a", "text": "In flight starting, according to the speed and altitude", "correct": false}, {"id": "b", "text": "Ventilation", "correct": true}, {"id": "c", "text": "Ground starting", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Before starting a twin-spool turbojet with variable inlet guide vanes and compressor bleed valves, which positions are normally required?', '[{"id": "a", "text": "Inlet guide vanes at minimum opening and bleed valves open", "correct": true}, {"id": "b", "text": "Inlet guide vanes fully open and bleed valves closed", "correct": false}, {"id": "c", "text": "Inlet guide vanes fully open and bleed valves open", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Where is the oil cooler placed in a cold-tank lubrication system?', '[{"id": "a", "text": "There is no dwell-tank in the oil tank", "correct": false}, {"id": "b", "text": "The oil cooler is placed in the scavenger system", "correct": true}, {"id": "c", "text": "The oil cooler is placed in the high-pressure system", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a resistive type detector the dielectric has a negative coefficient if the temperature increases then the resistance:', '[{"id": "a", "text": "Increases", "correct": false}, {"id": "b", "text": "Remain constant", "correct": false}, {"id": "c", "text": "Decreases", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'On an aircraft turbine engine operating at constant power the application of engine anti-icing will result in:', '[{"id": "a", "text": "Mass airflow decreases/EPR increases", "correct": false}, {"id": "b", "text": "Mass airflow decreases/EPR decreases", "correct": true}, {"id": "c", "text": "Mass airflow increases/EPR decreases", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which of the following types of combustion chambers are used in aircraft turbine engines?', '[{"id": "a", "text": "Can, multiple can and variable", "correct": false}, {"id": "b", "text": "Multiple-can, annular and can-annular combustion chambers", "correct": true}, {"id": "c", "text": "Annular, variable and cascade vane", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Thermocouple used in the EGT indication systems in a turbo jet engine are made from which of the following materials?', '[{"id": "a", "text": "Chromel/alumel", "correct": true}, {"id": "b", "text": "Iron/constant", "correct": false}, {"id": "c", "text": "Copper/constant", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is a representative gas temperature on entering the first turbine stage of an earlier- generation gas turbine?', '[{"id": "a", "text": "500-700C", "correct": false}, {"id": "b", "text": "300-400C", "correct": false}, {"id": "c", "text": "1100-1300C", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An APU over temperature condition causes:', '[{"id": "a", "text": "A deceleration to idle", "correct": false}, {"id": "b", "text": "An automatic shut-off", "correct": true}, {"id": "c", "text": "A visual warning in the flight deck", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What does a duplex fuel nozzle provide?', '[{"id": "a", "text": "Primary fuel flow for starting and main fuel flow for running conditions", "correct": true}, {"id": "b", "text": "Additional to increase normal maximum power", "correct": false}, {"id": "c", "text": "A fuel and water spray via the same orifice", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which of the following statements with respect to gas turbine engine is correct?', '[{"id": "a", "text": "As a result of lower air density consumption at high altitudes will be higher", "correct": false}, {"id": "b", "text": "At high engine speeds a small movement of the throttle has an important effect on the generated thrust", "correct": true}, {"id": "c", "text": "At low engine speeds a small movement of the throttle has an important effect on the generated thrust", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which ambient temperature change generally improves gas-turbine performance, other conditions being equal?', '[{"id": "a", "text": "A decrease in ambient temperature", "correct": true}, {"id": "b", "text": "A decrease in ambient air pressure", "correct": false}, {"id": "c", "text": "An increase in ambient air temperature", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the purpose of an oil-damped bearing?', '[{"id": "a", "text": "To allow for engine growth", "correct": false}, {"id": "b", "text": "Eliminate axial movement on engine shafts", "correct": false}, {"id": "c", "text": "To reduce engine vibration", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Engine accessories are generally cooled by:', '[{"id": "a", "text": "High-pressure compressor air supply", "correct": false}, {"id": "b", "text": "Air from the air conditioning system", "correct": false}, {"id": "c", "text": "Ram air", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the function of an active turbine-tip clearance control system?', '[{"id": "a", "text": "Clearance adjustment by a regulated air blast on the high-pressure compressorvariable stator vanes as a", "correct": false}, {"id": "b", "text": "Clearance adjustment by an unregulated air blast on the high-pressure and low-pressure turbine casing as a", "correct": false}, {"id": "c", "text": "Regulated cooling air on turbine casings, controlled by the engine control unit", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'At a fixed throttle setting and with increasing altitude the fuel supply to the burners:', '[{"id": "a", "text": "Remains substantially constant", "correct": false}, {"id": "b", "text": "Is gradually decreased by automatic device", "correct": true}, {"id": "c", "text": "Is increased gradually by an automatic device", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What functions are typically initiated when the engine fire handle is pulled (before bottle discharge)?', '[{"id": "a", "text": "Closes all fire wall shut-off valves, disconnects the generator and discharges the fire bottle", "correct": false}, {"id": "b", "text": "Closes fuel shut-off, closes hydraulic shut-off, closes the oxygene shut-off, disconnects the generator field and", "correct": false}, {"id": "c", "text": "Close fuel and hydraulic shut-off valves, disconnect the generator field and arm the fire extinguishing", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What energy conversion is performed by the turbine section?', '[{"id": "a", "text": "Convert thermal energy into kinetic energy", "correct": false}, {"id": "b", "text": "Convert kinetic energy into thermal energy", "correct": false}, {"id": "c", "text": "Convert kinetic energy into mechanical energy", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What component is used to sense vibration on gas turbine engine?', '[{"id": "a", "text": "An out of phase sequencer", "correct": false}, {"id": "b", "text": "An accelerometer", "correct": true}, {"id": "c", "text": "An oscillator", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'When a twin spool engine is operated at high altitudes the:', '[{"id": "a", "text": "Low-pressure rotor will decrease in speed as the compressor load decreases in the lower density air", "correct": false}, {"id": "b", "text": "Throttle must be retarded to prevent over speeding of the high-pressure rotor due to the lower density air", "correct": false}, {"id": "c", "text": "Low-pressure rotor will increase in speed as compressor load decreases in the lower air temperature ✓", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Where is a resistance placed in order to limit the starting current of an engine starter motor?', '[{"id": "a", "text": "In parallel with the motor armature", "correct": false}, {"id": "b", "text": "In series with the motor armature", "correct": true}, {"id": "c", "text": "In parallel with the motor field", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Where does the largest static pressure rise usually occur in a centrifugal compressor?', '[{"id": "a", "text": "In the compressor wheel", "correct": false}, {"id": "b", "text": "In the inlet to the combustion chamber", "correct": false}, {"id": "c", "text": "In the diffuser", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What conditions usually permit thrust-reverser deployment?', '[{"id": "a", "text": "Weight on wheels, switch activated, throttle lever in the idle position", "correct": true}, {"id": "b", "text": "Correct aircraft speed for landing, throttle lever on full reverse", "correct": false}, {"id": "c", "text": "Over travel of idle stop, ground spoiler deployed", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'For an equal airflow, which compressor typically has a smaller frontal area?', '[{"id": "a", "text": "The radial compressor has the smallest frontal area", "correct": false}, {"id": "b", "text": "The axial compressor has the smallest frontal area", "correct": true}, {"id": "c", "text": "The radial compressor has the greatest stall tendency", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'At constant RPM, altitude and airspeed, what happens to thrust as ambient temperature decreases?', '[{"id": "a", "text": "The thrust decreases to a given temperature before increasing again", "correct": false}, {"id": "b", "text": "The thrust decreases", "correct": false}, {"id": "c", "text": "The thrust increases", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'When in operation the speed of an APU:', '[{"id": "a", "text": "Remains at or near rated speed regardless of the load condition", "correct": true}, {"id": "b", "text": "Remains at idle and automatically accelerates to rated speed when placed under load", "correct": false}, {"id": "c", "text": "Is controlled by a cockpit power lever", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the most likely cause when oil leaks from a main oil filter housing?', '[{"id": "a", "text": "A defective carbon seal", "correct": false}, {"id": "b", "text": "A defective labyrinth seal", "correct": false}, {"id": "c", "text": "A defective \"O\" ring", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'If an engine is flat-rated to 30°C, what happens to its maximum available thrust when ambient temperature rises to 35°C?', '[{"id": "a", "text": "The spool rotational speed will be exceeded", "correct": false}, {"id": "b", "text": "The maximum power cannot be obtained", "correct": true}, {"id": "c", "text": "The turbine outlet temperature will be exceeded", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the purpose of the diffuser section in the turbine engine?', '[{"id": "a", "text": "Reduce velocity and increase pressure", "correct": true}, {"id": "b", "text": "Reduce velocity and reduce pressure", "correct": false}, {"id": "c", "text": "Increase velocity and reduce pressure", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Loss of power during take-off on a turbine engine could be due to:', '[{"id": "a", "text": "Too high fuel flow", "correct": false}, {"id": "b", "text": "One igniter unserviceable", "correct": false}, {"id": "c", "text": "Compressor bleed air valve open", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the main advantage of the can-annular chamber system?', '[{"id": "a", "text": "The chambers are short in length making the engine compact", "correct": false}, {"id": "b", "text": "The individual cans are simple to remove for maintenance", "correct": true}, {"id": "c", "text": "The flame tubes have a small wall area making the system very efficient", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which statement best describes a free-power-turbine turboshaft engine?', '[{"id": "a", "text": "The power turbine and the free turbine rotate at different speeds, the free turbine always being higher to", "correct": false}, {"id": "b", "text": "The power turbine and the free turbine rotate at the same speed", "correct": false}, {"id": "c", "text": "The gas-generator turbine runs at its governed speed, while the free-power turbine speed varies with", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'If during a take-off check an engine does not meet the minimum performance requirements, a possible cause can be:', '[{"id": "a", "text": "Bleed valve final orifice obstructed", "correct": false}, {"id": "b", "text": "Bleed valve leaking", "correct": true}, {"id": "c", "text": "Bleed valve closed with throttle at idle", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which set of methods is commonly used to improve compressor stability?', '[{"id": "a", "text": "Multi-spool layout, compressor bleed valves and variable inlet guide/stator vanes", "correct": true}, {"id": "b", "text": "Variable rotor vanes, bleed valves and triple spool layout", "correct": false}, {"id": "c", "text": "Sliding ring bleed valves, variable inlet guide vanes and single spool layout", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which of the following fuel nozzles requires the use of a P & D (pressurisation and dump) valve?', '[{"id": "a", "text": "Heat vaporizing nozzles", "correct": false}, {"id": "b", "text": "Simplex nozzles", "correct": false}, {"id": "c", "text": "Duplex nozzles", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What type of reduction gear is used by most modern turbo props?', '[{"id": "a", "text": "Epicyclic reduction gear", "correct": true}, {"id": "b", "text": "Helical-cut parallel spur gears", "correct": false}, {"id": "c", "text": "Straight-cut parallel spur gears", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the purpose of a corrugated exhaust nozzle?', '[{"id": "a", "text": "To allow ambient air to be sucked in the exhaust unit mixing cold and hot air to cool the exhaust gases", "correct": false}, {"id": "b", "text": "To reduce sound that is created in exhaust nozzle by increasing the surface area of the nozzle ✓", "correct": true}, {"id": "c", "text": "To produce more power by producing a sonic shock", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What type of oil is normally used in turboprop engines?', '[{"id": "a", "text": "High viscosity synthetic oil", "correct": false}, {"id": "b", "text": "High viscosity mineral oil", "correct": false}, {"id": "c", "text": "Low viscosity synthetic oil", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In general an APU will provide:', '[{"id": "a", "text": "Generator drive up to the aircraft altitude ceiling", "correct": true}, {"id": "b", "text": "Pneumatic drive up to the aircraft altitude ceiling", "correct": false}, {"id": "c", "text": "Either shaft or pneumatic power but not both up to the aircraft ceiling", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which of the following conditions is usually not acceptable to any extend in turbine blades?', '[{"id": "a", "text": "Pits", "correct": false}, {"id": "b", "text": "Cracks", "correct": true}, {"id": "c", "text": "Dents", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The resultant axial force on a main shaft of a gas turbine engine is normally taken by a:', '[{"id": "a", "text": "Ball bearing", "correct": true}, {"id": "b", "text": "Plain bearing", "correct": false}, {"id": "c", "text": "Roller bearing", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'The ignition systems are used:', '[{"id": "a", "text": "Only during engine start-up", "correct": false}, {"id": "b", "text": "During engine start-up and in flight phases with risk of flame extinction", "correct": true}, {"id": "c", "text": "In hazardous flight phases and during take-off", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'With a variable geometry inlet duct, subsonic conditions are met by:', '[{"id": "a", "text": "Decreasing throat area", "correct": false}, {"id": "b", "text": "Increasing jet pipe area", "correct": false}, {"id": "c", "text": "Increasing throat area", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In an axial-flow compressor stage (ignoring inlet guide vanes), which component follows first?', '[{"id": "a", "text": "Rotor blade, stator blade", "correct": true}, {"id": "b", "text": "Stator blade, rotor blade", "correct": false}, {"id": "c", "text": "Rotor blade, nozzle guide vane", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'From where does a FADEC engine’s electronic engine control normally receive power at ground idle?', '[{"id": "a", "text": "The hot battery bus", "correct": false}, {"id": "b", "text": "A dedicate generator driven by the engine", "correct": true}, {"id": "c", "text": "The aircraft main generators", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Kerosene is used as turbine engine fuel because:', '[{"id": "a", "text": "Kerosene has very high volatility which aids in ignition and lubrication", "correct": false}, {"id": "b", "text": "Kerosene has more heat energy per gallon than gasoline and lubricates fuel system", "correct": true}, {"id": "c", "text": "Kerosene does not contain any water", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'For subsonic airflow through a diverging duct, which changes are expected?', '[{"id": "a", "text": "Pressure decreases, temperature decreases and velocity increases", "correct": false}, {"id": "b", "text": "Temperature decreases, velocity increases and pressure increases", "correct": false}, {"id": "c", "text": "Velocity decreases, pressure increases and temperature increases", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Turbine nozzle diaphragms located up stream of each turbine wheel are used in the gas turbine engine to:', '[{"id": "a", "text": "Increase the velocity of the gases flowing past this point", "correct": true}, {"id": "b", "text": "Decrease the velocity of the gases flowing past this point", "correct": false}, {"id": "c", "text": "Only direct the flow of gases into a correct angle of attack to the turbine blade", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a can-annular combustion chamber, what provides pressure equalisation between combustion cans?', '[{"id": "a", "text": "Swirl vanes", "correct": false}, {"id": "b", "text": "Interconnecting tubes", "correct": true}, {"id": "c", "text": "The cans have a constant volume", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Turbine blades of turbojet engine may exhibit stress rupture cracks usually:', '[{"id": "a", "text": "Across the leading or trailing edge at a high angle to the edge length", "correct": true}, {"id": "b", "text": "Along the leading or trailing edge parallel to the edge", "correct": false}, {"id": "c", "text": "Across the blade root, parallel to the fir-tree", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An exhaust cone placed aft of the turbine in a jet engine will cause the pressure in the first part of the exhaust duct to:', '[{"id": "a", "text": "Decrease and the velocity to increase", "correct": false}, {"id": "b", "text": "Increase and the velocity to decrease", "correct": true}, {"id": "c", "text": "Increase and the velocity to increase", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Anti-icing of jet engine air inlets is commonly accomplished by:', '[{"id": "a", "text": "Electrical heating elements inside the inlet guide vanes", "correct": false}, {"id": "b", "text": "Engine bleed air ducted through the critical areas", "correct": true}, {"id": "c", "text": "Electrical heating elements located within the engine air inlet cowling", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Magnetic chip detector are usually found in the:', '[{"id": "a", "text": "Breather subsystem", "correct": false}, {"id": "b", "text": "Oil pressure subsystem", "correct": false}, {"id": "c", "text": "Oil scavenge subsystem", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An APU is usually rotated during start by:', '[{"id": "a", "text": "A turbine impingement system", "correct": false}, {"id": "b", "text": "An electric starter", "correct": true}, {"id": "c", "text": "A pressure starter", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Why are throttle-control linkages rigged with cushion (spring-back) travel at their stops?', '[{"id": "a", "text": "Ensure control travel at fuel control unit never limited by cockpit quadrant", "correct": false}, {"id": "b", "text": "Compensate for friction that may develop in that system during service", "correct": false}, {"id": "c", "text": "Cushion the movement at end of travel and avoid possible impact damage limit stops control unit ✓", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An EEC normally operates in flight from power supplied by:', '[{"id": "a", "text": "A dedicated generator maintained in the engine gearbox", "correct": true}, {"id": "b", "text": "The aircraft essential DC bus", "correct": false}, {"id": "c", "text": "The hot battery bus", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In an axial compressor the pressure rise in rotor and the stator is approximately:', '[{"id": "a", "text": "Half in rotor half is stator", "correct": true}, {"id": "b", "text": "One third in the rotor two thirds in the stator", "correct": false}, {"id": "c", "text": "Two thirds in the rotor one third in the stator", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'On a twin spool engine at idle power the high-pressure compressor''s RPM are at:', '[{"id": "a", "text": "The same speed", "correct": false}, {"id": "b", "text": "Slower than the low-pressure compressor", "correct": false}, {"id": "c", "text": "Faster than the low-pressure compressor", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In an APU which signals are necessary to control the (IGV) of the compressor?', '[{"id": "a", "text": "Bleed demand signals, fuel pressure, IGV actuator and APU exhaust", "correct": false}, {"id": "b", "text": "Bleed demand signals, air pressure and temperature, IGV actuator feedback", "correct": true}, {"id": "c", "text": "Bleed demand signals, APU speed signal and oil pressure", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a clamshell-door thrust reverser, in what approximate direction is the exhaust deflected?', '[{"id": "a", "text": "Discharged at approximately 45° to thrust line", "correct": true}, {"id": "b", "text": "Discharged at 90° to the thrust line", "correct": false}, {"id": "c", "text": "Fully reverse", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a DC electric engine-starter circuit, what can DE-ENERGISE the starter motor after the engine starts?', '[{"id": "a", "text": "Increasing current taken by the motor energizing an overspeed relay", "correct": false}, {"id": "b", "text": "Decreasing current taken by the motor, de-energizing an overspeed relay", "correct": false}, {"id": "c", "text": "A starter-motor centrifugal switch de-energises the hold-in coil of the starter contactor", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'When water–methanol is injected into a gas turbine, what roles does the methanol serve?', '[{"id": "a", "text": "Important additional source of fuel", "correct": false}, {"id": "b", "text": "Anti-freeze only", "correct": false}, {"id": "c", "text": "Important additional source of fuel and an anti-freeze", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What indication can result when a compressor surge-control bleed valve fails to close at take-off power?', '[{"id": "a", "text": "Higher than normal exhaust gas temperature at take-off power setting", "correct": true}, {"id": "b", "text": "Fluctuating exhaust gas temperature at take-off power setting", "correct": false}, {"id": "c", "text": "Lower than normal EGT in take -off power setting", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Adding heat in the gas-turbine combustion chamber produces a large:', '[{"id": "a", "text": "Expansion with an increase in static pressure", "correct": false}, {"id": "b", "text": "Increase in pressure at constant volume", "correct": false}, {"id": "c", "text": "Expansion at approximately constant static pressure", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Nozzle guide vanes are positioned:', '[{"id": "a", "text": "At compressor exit", "correct": false}, {"id": "b", "text": "At turbine exit", "correct": false}, {"id": "c", "text": "At combustion chamber exit", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Air starter rotating parts are lubricated by:', '[{"id": "a", "text": "An oil reservoir in the starter", "correct": true}, {"id": "b", "text": "Grease applied with a grease gun", "correct": false}, {"id": "c", "text": "A drip-feed with system", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Main bearing oil seal used with turbine engines are usually what type?', '[{"id": "a", "text": "Labyrinth and/or silicon rubber", "correct": false}, {"id": "b", "text": "Labyrinth and/or carbon", "correct": true}, {"id": "c", "text": "Teflon and synthetic rubber", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Where an engine is designed to operate with a free turbine:', '[{"id": "a", "text": "There is a clutch between compressor and power output shaft", "correct": false}, {"id": "b", "text": "There is a direct drive with a free wheel unit", "correct": false}, {"id": "c", "text": "There is no mechanical connection with the compressor", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In case of an engine running at idle RPM the bleed valves are:', '[{"id": "a", "text": "Closed", "correct": false}, {"id": "b", "text": "In an arbitrary position", "correct": false}, {"id": "c", "text": "Opened", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the purpose of directing fan air or compressor air over the outer casings of light pressure and low-pressure turbines:', '[{"id": "a", "text": "To cool and shrink the casings to minimize air losses around the turbine blade tips", "correct": true}, {"id": "b", "text": "To cool the turbine casings and their reduce age hardering of the metal", "correct": false}, {"id": "c", "text": "To prevent overheat of the turbine casings and therefore reduce fire risk", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which protection may prevent fuel-flow transmitter damage if its moving vane jams?', '[{"id": "a", "text": "A differential pressure sensing by-pass valve", "correct": true}, {"id": "b", "text": "A pressure relief valve", "correct": false}, {"id": "c", "text": "Vibrating the vane", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a single spool turbine engine how is cooling air fed to turbine blades?', '[{"id": "a", "text": "Via a hollow belt surrounding the blade tips", "correct": false}, {"id": "b", "text": "Via holes in the face of the turbine disc periphery", "correct": false}, {"id": "c", "text": "Via holes in the base of each blade", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'When servicing the engine oil of a turbo jet engine where the oil level is not checked after shut- down before the first flight of the day it is necessary to:', '[{"id": "a", "text": "Service the oil tank adding oil as needed", "correct": false}, {"id": "b", "text": "Run the engine at idle for a short duration and then service the oil tank", "correct": true}, {"id": "c", "text": "Motor the engine for an extended period then service the oil tank", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What are the purposes of reweighing and hydrostatically testing an engine fire-extinguisher bottle, respectively?', '[{"id": "a", "text": "Serviceability of the bottle and system operation respectively", "correct": false}, {"id": "b", "text": "State of charge and system operation respectively", "correct": false}, {"id": "c", "text": "State of charge and serviceability of the bottle respectively", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Thrust bearing are usually:', '[{"id": "a", "text": "Ball", "correct": true}, {"id": "b", "text": "Tapered roller", "correct": false}, {"id": "c", "text": "Roller", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'When air is bled from the compressor stage of a turbine engine for de-icing purposes it normally results in:', '[{"id": "a", "text": "Gas temperature increased and specific fuel consumption increased", "correct": true}, {"id": "b", "text": "Gas temperature decreased and specific fuel consumption decreased", "correct": false}, {"id": "c", "text": "Gas temperature decreased and specific fuel consumption increased", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which combination of factors affects intake air density? (1) Airspeed, (2) compressor pressure ratio, (3) turbine inlet temperature, (4) altitude, (5) ambient temperature, (6) compressor/turbine efficiency.', '[{"id": "a", "text": "1, 3 and 6", "correct": false}, {"id": "b", "text": "1, 4 and 5", "correct": true}, {"id": "c", "text": "4, 5 and 6", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What effect has the tertiary airflow in the combustion chamber?', '[{"id": "a", "text": "Reduces the gas temperature and cools the burner side walls", "correct": true}, {"id": "b", "text": "Ensures the complete combustion of the fuel by producing a back pressure", "correct": false}, {"id": "c", "text": "Generates a swirling motion to slow the axial velocity of the air", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In addition to lubricating, engine oils are used:', '[{"id": "a", "text": "To provide hydraulic power to variable bleed/stator vanes", "correct": false}, {"id": "b", "text": "To seal bearing cavities", "correct": false}, {"id": "c", "text": "For dampening bearing vibrations", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the engine pressure ratio (EPR) indicator used to indicate?', '[{"id": "a", "text": "The ratio of engine RPM to compressor pressure", "correct": false}, {"id": "b", "text": "The pressure ratio between the front and the aft end of the compressor", "correct": false}, {"id": "c", "text": "The thrust being produced (as a thrust proxy)", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Turbo-prop engine torque indication is normally provided by the output of the sensor measuring pressure from:', '[{"id": "a", "text": "A tapping of the engine main oil gallery", "correct": false}, {"id": "b", "text": "Opposition to the movement of part of the reduction gear", "correct": true}, {"id": "c", "text": "The propeller controller", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'During a ground run, the engine exhaust total pressure is 21 psi and inlet total pressure is 14 psi. What is EPR?', '[{"id": "a", "text": "1.5", "correct": true}, {"id": "b", "text": "0.66", "correct": false}, {"id": "c", "text": "0.5", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What would be the possible cause if a gas turbine engine has high exhaust gas temperature, high fuel flow and low RPM at all engine power settings?', '[{"id": "a", "text": "Fuel control out of adjustment", "correct": false}, {"id": "b", "text": "Loose or corroded thermocouple probe for the EGT indicator", "correct": false}, {"id": "c", "text": "Turbine damage or loss of turbine efficiency", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Why are fixed (orifice) nozzles used in the lubrication system of gas turbine engines?', '[{"id": "a", "text": "To provide a relatively constant oil flow to the main bearing at all engine speeds", "correct": true}, {"id": "b", "text": "To protect the oil seals by preventing excessive pressure from entering the bearing cavities", "correct": false}, {"id": "c", "text": "To keep back pressure on the oil pump, thus preventing an air lock", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is the main purpose of a bellmouth air intake on a helicopter?', '[{"id": "a", "text": "Increase the pressure and velocity of the airflow", "correct": false}, {"id": "b", "text": "Increase the pressure and decrease the velocity of the airflow", "correct": false}, {"id": "c", "text": "Send smooth air flow to the compressor", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'At take-off, total engine airflow is 765 kg/s and bypass ratio is 5.12. What is the core (primary) airflow?', '[{"id": "a", "text": "640 kg/s", "correct": false}, {"id": "b", "text": "149 kg/s", "correct": false}, {"id": "c", "text": "125 kg/s", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'To open the APU bleed valve, the following conditions are necessary:', '[{"id": "a", "text": "Bleed switch ON and APU speed [missing value in original]", "correct": false}, {"id": "b", "text": "Bleed switch in ON position and APU EGT below shut – down limit", "correct": false}, {"id": "c", "text": "Bleed switch ON and APU speed above 95%", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'If a turbojet engine oil tank is overfull after flight, what is a possible cause?', '[{"id": "a", "text": "Air in system", "correct": false}, {"id": "b", "text": "Scavenge pump not efficient", "correct": false}, {"id": "c", "text": "Leaking fuel/oil cooler", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Usually most of the load placed on an APU occurs when:', '[{"id": "a", "text": "The bleed air valve is closed", "correct": false}, {"id": "b", "text": "The bleed air valve is opened", "correct": true}, {"id": "c", "text": "An electrical load is placed on the generator", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Which bearing seal uses interlocking machined rings?', '[{"id": "a", "text": "Ring seals", "correct": false}, {"id": "b", "text": "Carbon seals", "correct": false}, {"id": "c", "text": "Labyrinth seals", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'Turbine blade creep occurs due to:', '[{"id": "a", "text": "Blades being subjected to high temperature and high RPM over a period time", "correct": true}, {"id": "b", "text": "High turbine inlet pressure and high RPM at altitude", "correct": false}, {"id": "c", "text": "High gas velocity and high temperature over a period time", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'An annular combustor is characterised by:', '[{"id": "a", "text": "An individual inner-liner and an individual outer-liner", "correct": false}, {"id": "b", "text": "A common inner -liner and a common outer-liner enclosed in a casing", "correct": true}, {"id": "c", "text": "A number of inner-liner enclosed in a common outer-liner", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'In a dual-spool compressor/turbine system, the first turbine stage downstream of the combustor drives:', '[{"id": "a", "text": "N1 compressor", "correct": false}, {"id": "b", "text": "N2 compressor", "correct": true}, {"id": "c", "text": "N1 compressor and accessory gear box", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What is a consequence of creep in gas-turbine components?', '[{"id": "a", "text": "Increase the gap between the stator and rotor", "correct": false}, {"id": "b", "text": "Deteriorate the material of e.g. turbine blades", "correct": true}, {"id": "c", "text": "Push the turbine section rearwards", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M15.23'), 'What prevents agent from a second fire-extinguisher bottle from discharging backwards into an emptied bottle?', '[{"id": "a", "text": "An electrical sequencing circuit", "correct": false}, {"id": "b", "text": "Internal lock on the fire handle", "correct": false}, {"id": "c", "text": "Non-return valve", "correct": true}]'::jsonb, '{B1,B2}');
